92	    final email = await _secureTokenStorage.readAccountEmail() ?? '';
93	    // An in-progress name edit is never clobbered by a re-dispatched
94	    // SettingsOpened (research.md R15 — "any in-progress edit... not
95	    // silently lost").
96	    if (state.nameEditStatus != NameEditStatus.viewing) {
97	      emit(state.copyWith(email: email));
