108	    final visible = capability == BiometricCapability.available;
109	    final enabled = visible ? await _vaultRepository.isBiometricPreferenceEnabled() : false;
110	    emit(state.copyWith(biometricToggleVisible: visible, biometricEnabled: enabled));
