114	
115	  Future<void> _loadDashboard(Emitter<SettingsState> emit) async {
116	    emit(
117	      state.copyWith(
118	        dashboardStatus: DashboardStatus.loading,
119	        narrativeStatus: NarrativeStatus.notRequested,
120	        narrativeText: null,
121	        dashboardFailure: null,
122	      ),
123	    );
124	
125	    final aggregateResult = await _dashboardRepository.fetchAggregate();
126	    await aggregateResult.match(
127	      (failure) async {
128	        if (failure is AuthExpiredFailure) _reauthController.add(null);
