138	          state.copyWith(
139	            dashboardStatus: DashboardStatus.loaded,
140	            aggregate: aggregate,
141	            dashboardFailure: null,
142	          ),
143	        );
144	        // Only fetch the narrative once the aggregate resolves Right AND
145	        // its own total is >= 2 (FR-003/FR-004/FR-005/FR-006) — the bloc
146	        // inspects the already-resolved aggregate's own total, never a
147	        // second round-trip to "find out" the count.
