200	      // FR-011 — no backend call is made on an invalid draft.
201	      emit(
202	        state.copyWith(
203	          nameEditStatus: NameEditStatus.editing,
204	          nameEditFailureMessage: 'Informe um nome de até 80 caracteres.',
205	        ),
206	      );
207	      return;
208	    }
209	
210	    emit(state.copyWith(nameEditStatus: NameEditStatus.saving, nameEditFailureMessage: null));
211	    final result = await _accountProfileRepository.updateDisplayName(state.nameDraft.trim());
212	    result.match(
213	      (failure) {
214	        if (failure is AuthExpiredFailure) _reauthController.add(null);
215	        // FR-012 — stays editing, nameDraft intact, retryable message.
216	        emit(
217	          state.copyWith(
218	            nameEditStatus: NameEditStatus.editing,
219	            nameEditFailureMessage: failure.message,
220	          ),
221	        );
222	      },
223	      (confirmedName) {
224	        emit(
225	          state.copyWith(
226	            displayName: confirmedName,
227	            nameEditStatus: NameEditStatus.viewing,
228	            nameDraft: '',
229	            nameEditFailureMessage: null,
230	          ),
231	        );
232	      },
233	    );
234	  }
