236	  // --- Biometric toggle (contracts/biometric-preference-settings-extension.md) ---
237	
238	  Future<void> _onBiometricToggleChanged(
239	    BiometricToggleChanged event,
240	    Emitter<SettingsState> emit,
241	  ) async {
242	    final previousValue = state.biometricEnabled;
243	    // Optimistic flip (RNF01, <100ms) — reverted below on failure.
244	    emit(
245	      state.copyWith(
246	        biometricEnabled: event.value,
247	        biometricSaving: true,
248	        biometricFailureMessage: null,
249	      ),
250	    );
251	    final result = await _saveSettingsBiometricPreferenceUseCase(event.value);
252	    result.match(
253	      (failure) {
254	        if (failure is AuthExpiredFailure) _reauthController.add(null);
255	        emit(
256	          state.copyWith(
257	            biometricEnabled: previousValue,
258	            biometricSaving: false,
259	            biometricFailureMessage: failure.message,
260	          ),
261	        );
262	      },
263	      (_) {
264	        emit(state.copyWith(biometricSaving: false, biometricFailureMessage: null));
265	      },
266	    );
267	  }
