269	  // --- Sign-out (contracts/account-session-actions.md) ---
270	
271	  Future<void> _onSignOutRequested(
272	    SignOutRequested event,
273	    Emitter<SettingsState> emit,
274	  ) async {
275	    if (state.isSigningOut) return; // FR-022
276	    emit(state.copyWith(isSigningOut: true));
277	
278	    // Awaited so the request completes before local state is wiped, but
279	    // never branched on — FR-016's own wording clears the local session
280	    // "regardless of whether that call succeeds or fails".
281	    await _authRepository.logout();
282	    await _sessionRepository.clear();
283	    await _accountProfileRepository.clearCachedDisplayName();
284	
285	    final hasPinConfigured = await _vaultRepository.hasPinConfigured();
286	    emit(
287	      state.copyWith(
288	        isSigningOut: false,
289	        signedOutDestination:
290	            hasPinConfigured ? SettingsDestination.vault : SettingsDestination.login,
291	      ),
292	    );
293	  }
294	
295	  // --- Account deletion (contracts/account-deletion-repository.md) ---
296	
297	  void _onDeleteAccountDialogOpened(
298	    DeleteAccountDialogOpened event,
299	    Emitter<SettingsState> emit,
300	  ) {
301	    emit(state.copyWith(deleteDialogOpen: true, deleteFailureMessage: null));
302	  }
303	
304	  void _onDeleteAccountDialogCancelled(
305	    DeleteAccountDialogCancelled event,
306	    Emitter<SettingsState> emit,
307	  ) {
308	    // FR-021 — no backend call on cancel.
309	    emit(state.copyWith(deleteDialogOpen: false, deleteFailureMessage: null));
310	  }
311	
312	  Future<void> _onDeleteAccountConfirmed(
313	    DeleteAccountConfirmed event,
314	    Emitter<SettingsState> emit,
315	  ) async {
316	    if (state.isDeletingAccount) return; // FR-022
317	    emit(state.copyWith(isDeletingAccount: true, deleteFailureMessage: null));
318	
319	    final result = await _accountDeletionRepository.deleteAccount();
320	    await result.match(
321	      (failure) async {
322	        if (failure is AuthExpiredFailure) _reauthController.add(null);
323	        emit(state.copyWith(isDeletingAccount: false, deleteFailureMessage: failure.message));
324	      },
325	      (_) async {
326	        // research.md R9 — account deletion clears strictly more than
327	        // sign-out: session + cached profile (both actions) plus every
328	        // other locally held user data (deletion only).
329	        await _sessionRepository.clear();
330	        await _accountProfileRepository.clearCachedDisplayName();
331	        await _entriesRepository.clearLocalData();
332	        await _chatRepository.clearLocalData();
333	
334	        final hasPinConfigured = await _vaultRepository.hasPinConfigured();
335	        emit(
336	          state.copyWith(
337	            isDeletingAccount: false,
338	            deleteDialogOpen: false,
339	            accountDeletedDestination:
340	                hasPinConfigured ? SettingsDestination.vault : SettingsDestination.login,
341	          ),
342	        );
343	      },
344	    );
345	  }
346	
347	  @override
348	  Future<void> close() {
349	    unawaited(_reauthController.close());
350	    return super.close();
351	  }
352	}
